      <div class="field"><label for="founder-consent-reference">Permission record reference</label><input id="founder-consent-reference" name="consent_reference" maxlength="500" value="<?=e(journeys_field($review,'consent_reference'))?>"><small class="journey-help">Where the founder’s permission is documented, including the agreed name, venture, quotations and material. A private file reference or correspondence date is enough; do not paste access tokens.</small></div>
      <label class="journey-check"><input type="checkbox" name="permission_confirmed" value="1" <?=journeys_checked($review['permission_confirmed']??null)?'checked':''?>><span>I have confirmed the founder’s permission for the article and recorded its scope.</span></label>
      <label class="journey-check"><input type="checkbox" name="claims_reviewed" value="1" <?=journeys_checked($review['claims_reviewed']??null)?'checked':''?>><span>I have reviewed the claims and their basis. The article distinguishes supported findings, estimates and personal accounts.</span></label>
      <datalist id="founder-post-options"><?php foreach($postOptions as $option):?><option value="<?=(int)$option['id']?>"><?=e($option['title'])?> (<?=e($option['status'])?>)</option><?php endforeach;?></datalist>
      <div class="field"><label for="founder-associated-post">Associated post ID <span class="optional">(optional during review)</span></label><input id="founder-associated-post" name="associated_post_id" inputmode="numeric" pattern="[1-9][0-9]*" list="founder-post-options" value="<?=e(journeys_field($review,'associated_post_id'))?>"><small class="journey-help">Publish the reviewed article through the writing library. Only an already published article can be enabled in Founder Stories.</small></div>
      <label class="journey-check journey-check-emphasis"><input type="checkbox" name="is_public" value="1" <?=journeys_checked($review['is_public']??null)?'checked':''?>><span>Include the approved article in the public Founder Stories collection.</span></label>
